// mixedSatRegressGet answers Get's own
// value with Rev walked backwards, and every other member left as
// the subject set it.
//
// One member rather than the whole value, because the session laws read the
// key off the same answer they order. A wear replacing the value files each
// read under a different key, and a law that never compares two reads of one
// key cannot fail — which is what every zero-answering defect did here.
//
// The stamp descends from whatever the subject last returned, so the second
// read of a key is strictly older than the first however the subject numbers
// its versions.
type mixedSatRegressGet struct {
	monotonicreads.Mixed
	mu   sync.Mutex
	held bool
	prev monotonicreads.Value
}

func (m *mixedSatRegressGet) Get(p0 context.Context, p1 string) (monotonicreads.Value, error) {
	out, err := m.Mixed.Get(p0, p1)
	if err != nil {
		return out, err
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.held {
		out.Rev = m.prev.Rev - 1
	}
	m.held, m.prev = true, out
	return out, nil
}

